import{_ as n}from"./chunks/editor-zeichnung.C5iY_LPV.js";import{_ as i,o as t,c as r,a3 as a}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"HA Grafik Visual Studio","description":"Das etwas andere Dashboard für Home Assistant: aktueller Entwicklungsstand und Bedienung.","frontmatter":{"title":"HA Grafik Visual Studio","description":"Das etwas andere Dashboard für Home Assistant: aktueller Entwicklungsstand und Bedienung."},"headers":[],"relativePath":"projects/grafik-visual-studio/index.md","filePath":"projects/grafik-visual-studio/index.md","lastUpdated":1793118610000}'),s={name:"projects/grafik-visual-studio/index.md"};function d(o,e,l,u,g,h){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="ha-grafik-visual-studio" tabindex="-1">HA Grafik Visual Studio <a class="header-anchor" href="#ha-grafik-visual-studio" aria-label="Permalink to &quot;HA Grafik Visual Studio&quot;">​</a></h1><p><strong>Studio 0.1.296:</strong> Die übrigen <strong>62 Widgettypen</strong> erhalten DE/EN/FR-Eigenschaften und Laufzeitmeldungen, optionale Climate-Steuerung sowie Quellen-/Attribut-/Einheitenprüfung. Bestehende Projekte und Paketversionen bleiben gültig; neue Gruppen starten deaktiviert. <a href="./ha-quellen-climate">Anleitung und Grenzen</a>. Echte Geräte/Companion sind durch simulierte Tests noch nicht bestätigt. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/ha_grafik_visual_studio/docs/remaining-widget-audit-2026-10-12.md" target="_blank" rel="noreferrer">Prüfbericht</a>.</p><p>Seit <strong>0.1.289</strong> wechselt <strong>Speichern</strong> während des Speicherns kurz die Farbe: <strong>Orange</strong> bei laufender Anfrage, <strong>Grün</strong> nach Erfolg und <strong>Rot</strong> bei einem Fehler. Nach 1,4 Sekunden kehrt die normale Farbe zurück. Das gilt auch für Autospeichern und funktioniert bei heller und dunkler Darstellung.</p><p>Ab <strong>Studio 0.1.287</strong> haben <strong>alle Widgets</strong> oben im Reiter <strong>WIDGET</strong> die Checkbox <strong>In Runtime verstecken</strong>. Sie blendet das Widget unabhängig vom Z-Index in der Runtime aus; im Editor bleibt es bearbeitbar. Berechnungen und Datenfluss bleiben aktiv, auch bei ausgeblendeten Number-Widgets und MathBoxen. Das Projekt nach der Änderung speichern.</p><p>Weitere Änderungen bis <strong>Studio 0.1.285</strong>: <a href="./svg-line">SVG-Line</a> und Wert-Verbindung erhalten vertikale Startpositionen und senkrechte rechtwinklige Pfadführung sowie weniger empfindliches Punktziehen. <a href="./industrial">Poti-Ausgänge</a> steuern die Linienanimation direkt. Das <a href="./svg-linebox-math">Number→Math-Beispiel</a> erklärt <code>O - P</code> für den Batterie-Nettofluss; <a href="./bildergalerie">Galerie</a> mit Editorbild vor der animierten Demo.</p><p>Neu ab Studio <strong>0.1.280</strong>: <a href="./solar">Solar 0.1.3</a> bietet sieben Linienpunkte an der Unterkante des Solo-Wechselrichters. Enthält außerdem vier Solarpanel-Eingänge am Stapel-Kopfteil, Batterieanschlüsse an der Gehäusenaht, getrennte Batterie-Wertfarben und ein spiegelbares Solarpanel mit Standfuß.</p><p>Neu ab Studio <strong>0.1.215</strong>: Das externe <a href="./materialdesign">Material-Design-Set 1.0.0</a> enthält <strong>49 Widget-Einträge</strong>, Autocomplete, Eingaben, Buttons, Anzeigen, Listen, Diagramme, Kalender und Seitenlayouts. Ein Vergleichsprojekt bereitet die Prüfung Widget für Widget vor.</p><p>Neu ab Studio <strong>0.1.214</strong>: Material-Design-Paket <strong>0.3.0</strong> ergänzt <a href="./materialdesign">Dialog iFrame</a> als drittes Widget mit Quelle, Sandbox, Scrolloptionen und kompaktem/erweitertem Dialoglayout.</p><p>Neu ab Studio <strong>0.1.210</strong>: Das externe <a href="./materialdesign">Material-Design-Set</a> startet mit <strong>Preview Color Schemes</strong>, 26 Farbreihen und Klassisch/Material 3/Projektstandard. Paket 0.1.0 ist für den Registrierungstest im Community-Katalog vorbereitet.</p><h2 id="paketkatalog-und-downloads" tabindex="-1">Paketkatalog und Downloads <a class="header-anchor" href="#paketkatalog-und-downloads" aria-label="Permalink to &quot;Paketkatalog und Downloads&quot;">​</a></h2><p>Das Paket <strong>Wetter und Heizung 1.7.1</strong> zeigt für sieben Widgets die jeweiligen Original-Vorschaubilder aus <a href="https://github.com/rg-engineering/ioBroker.vis-2-widgets-weather-and-heating" target="_blank" rel="noreferrer">ioBroker weather-and-heating</a>. „Meinen Vermieter informieren“ erhält ein Briefsymbol, da die im Original referenzierte Bilddatei fehlt. Die MIT-Lizenz der Originalbilder liegt dem Paket bei. Das Update ändert ausschließlich Widget-Bilder; bestehende Einstellungen bleiben erhalten. Für das Bild-Update wird Studio <strong>0.1.216</strong> oder neuer benötigt.</p><p>Ab Katalog-Webseite <strong>0.1.11</strong> wird ein bei der Registrierung hochgeladenes Originalpaket privat für die Adminprüfung gespeichert. Analyse und Freigabe verwenden diese Datei ohne erneuten Upload; eine neue Datei kann optional als Ersatz hochgeladen werden. Die Administration kann das Original herunterladen. SHA-256 erkennt Änderungen. Die private Kopie wird nach Freigabe, Ablehnung, Löschung oder Ablauf der 90-Tage-Aufbewahrung entfernt. Bei älteren Einreichungen ist einmalig ein erneuter Upload nötig, weil frühere Versionen die Datei nur analysiert haben.</p><p>Ab Katalog-Webseite <strong>0.1.10</strong> akzeptiert die Widget-Registrierung ausschließlich <code>.wg</code>, die Tool-Registrierung ausschließlich <code>.tp</code>. Die Dateiauswahl zeigt nur die passende Endung. Der Server prüft die Endung von Upload-Dateinamen und Download-Link-Pfaden sowie weiterhin Paketinhalt und Manifest-Typ. Die Upload-Prüfung gilt auch in der Administration.</p><p>Mit Katalog-Webseite <strong>0.1.9</strong> fragt die Registrierung nach neuen Studio-Funktionen (Ja/Nein/Unsicher); bei Ja oder Unsicher ist eine Beschreibung erforderlich und die Mindestversion kann als „Noch unbekannt“ angegeben werden. Bei Nein ist eine konkrete Mindestversion Pflicht. Die Administration legt die Mindestversion bei der Prüfung und nach einer erforderlichen Studio-Anpassung fest; vor der Freigabe muss eine konkrete Version eingetragen sein. Ein optionaler Paket-Upload erkennt die verwendeten Renderer/Aktionen; ohne Datei erfolgt die Analyse in der Administration. Unbekannte Funktionen erhalten „Studio-Anpassung erforderlich“ und bleiben bis zur Umsetzung und erneuten Prüfung außerhalb des öffentlichen Katalogs. Das Webseiten-Update muss vom Betreiber hochgeladen werden.</p><p>Ab Studio <strong>0.1.212</strong> kennzeichnet ein rotes <code>mdi:alert</code>-Symbol die GitHub-Auswahl und den Installationshinweis bei Widget- und Tool-Paketen. Vor der Installation muss das Installationsrisiko bestätigt werden.</p><p>Ab Studio <strong>0.1.213</strong> erhalten verfügbare Paketupdates einen grünen Kartenrahmen. Bei neuen, kompatiblen Paketen wird nur der <strong>Installieren</strong>-Button blau hervorgehoben. Nach erfolgreicher Installation oder Aktualisierung entfällt die Markierung.</p><p>Studio erkennt neue freigegebene Paketversionen beim Öffnen der Paketeinstellungen oder über <strong>Katalog aktualisieren</strong> und bietet <strong>Aktualisieren</strong> an. Dafür müssen die Paket-IDs übereinstimmen; das gilt auch für vorher lokal oder über GitHub installierte Pakete. Updates werden bewusst installiert. Beliebige GitHub-Repositories werden nicht automatisch überwacht.</p><p>Widget-Pakete, Tool-Pakete und Zusatztools findest du zentral im <a href="https://visualstudio.ugso-software.de/?lang=de" target="_blank" rel="noreferrer">UGSo-Paketkatalog auf visualstudio.ugso-software.de</a>. Dazu gehören Technic, Wetter/Heizung, der Colorpicker sowie <strong>Widget Test</strong> und <strong>Tools Test</strong> für die Prüfung der Paketinstallation. Der <strong>Packer für Windows und Linux</strong> steht dort unter <strong>Zusatztools</strong> bereit. Beschreibung und Anleitung bleiben auf dieser Open-Source-Seite; Paketdateien werden über die Katalog-Subdomain angeboten.</p><p><strong>Das etwas andere Dashboard für Home Assistant.</strong> Grafik Visual Studio ist eine experimentelle Home-Assistant-App mit freier Editorfläche und getrennter Runtime. Das Projekt befindet sich in einer frühen Entwicklungsphase; Format und Bedienung können sich ändern. Es ist derzeit nicht für produktive Dashboards gedacht.</p><p><a href="./editor">Editor und Tastenkombinationen</a> · <a href="./widgets">Alle 74 Widgets</a> · <a href="./svg-line">SVG-Line</a> · <a href="./svg-linebox">SVG LineBox mit Videos</a> · <a href="./svg-linebox-math">SVG LineBox Math</a> · <a href="./widget-pakete">Widget-Paket-Schnittstelle</a> · <a href="./tool-pakete">Tool-Paket-Schnittstelle</a> · <a href="./packer">Packer für Pakete</a> · <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_grafik_visual_studio" target="_blank" rel="noreferrer">Quellcode und Home-Assistant-App</a></p><p><img src="'+n+'" alt="Editor von HA Grafik Visual Studio mit Widget-Palette und SVG-Verbindungslinien"></p><p><em>Editoransicht mit gezeichneten Verbindungslinien. <a href="/images/grafik-visual-studio/editor-zeichnung.png">Bild in voller Auflösung öffnen</a>.</em></p><h2 id="was-derzeit-moglich-ist" tabindex="-1">Was derzeit möglich ist <a class="header-anchor" href="#was-derzeit-moglich-ist" aria-label="Permalink to &quot;Was derzeit möglich ist&quot;">​</a></h2><p>Ab Studio <strong>0.1.222</strong> ist die Arbeitsfläche im hellen Theme grau mit anthrazitfarbenen Rasterlinien. Im dunklen Theme bleibt der bisherige Hintergrund erhalten; etwas hellere Rasterlinien erleichtern die Orientierung. Diese Darstellung betrifft den Editor. Die Runtime verwendet weiterhin den gespeicherten Seitenhintergrund.</p><p>Ab Studio <strong>0.1.221</strong> folgt die Oberfläche automatisch der Hell-/Dunkel-Einstellung, die der Browser meldet. Werkzeugleiste, Seitenleisten, Dialoge und Eingabefelder wechseln auch während der Nutzung ohne Neuladen. Gespeicherte Seitenhintergründe und Widgetfarben bleiben erhalten; der Theme-Wechsel verändert keine gespeicherten Projekteinstellungen.</p><p>Ab Studio <strong>0.1.220</strong> öffnen neue Seiten direkt den Reiter <strong>ANSICHT</strong>. Dort stehen CSS allgemein, Hintergrund, Schrift und Text, Optionen, Navigation, Anwendungsleiste und responsive Einstellungen zur Verfügung. Die Bereiche lassen sich auf- und zuklappen, haben aber keine Aktivierungscheckboxen: Seitenwerte bleiben beim Speichern erhalten. Die Checkboxen für einzelne Optionen wie „Standard“ bleiben bestehen.</p><p>Ab Studio <strong>0.1.218</strong> erscheinen fehlgeschlagene HA-Schaltbefehle als rote Meldung in der Runtime mit Entity-ID und Fehlerursache. Ab <strong>0.1.219</strong> zeigt auch ein Klick auf einen gesperrten Switch den Grund an, beispielsweise einen fehlenden oder nicht verfügbaren HA-Zustand. Schaltbare Widgets bedienen Home Assistant in der Runtime; im Editor dient die Bedienung der Vorschau.</p><p>Ab Studio <strong>0.1.217</strong> sucht der Entitäten-Dialog nach Anzeigenamen, benutzerdefinierten und ursprünglichen Entitätsnamen, Entity-IDs sowie Gerätenamen. Mehrere Suchwörter dürfen über Entität und Gerät verteilt sein: <strong>Licht Tv1</strong> findet beispielsweise eine Entität namens „Licht“ am Gerät „TV1“. Die Suche ignoriert Groß-/Kleinschreibung; passende Gerätegruppen werden während der Suche automatisch aufgeklappt.</p><ul><li>Im Dateien-Fenster sucht das Suchfeld in allen Unterordnern von <code>/config/www/studio</code>, unabhängig vom geöffneten Ordner. Die Suche ignoriert Groß-/Kleinschreibung und berücksichtigt Dateinamen sowie Pfade. Treffer zeigen eine Bildvorschau und den relativen Pfad; Dateitypfilter und Bildübernahme bleiben nutzbar. Ein leeres Suchfeld zeigt wieder den geöffneten Ordner.</li><li>Mehrfach ausgewählte Widgets lassen sich durch Ziehen eines ausgewählten Widgets gemeinsam verschieben, auch nach Kopieren und Einfügen. Ausgewählte SVG-Linien und Zwischenpunkte wandern mit; bestehende Andockverbindungen bleiben erhalten. Gesperrte Widgets verhindern das gemeinsame Verschieben. Ein Zug lässt sich als Ganzes rückgängig machen.</li><li>Die Widget-Auswahlliste bleibt vor allen Widgets sichtbar. Ab <strong>0.1.209</strong> werden die angehakten Widgets über <strong>Kopieren</strong> und <strong>Löschen</strong> in der Werkzeugleiste bearbeitet; die doppelten Buttons unten in der Liste entfallen. Beim Löschen gilt der Bestätigungsdialog.</li><li>Beim Löschen von Widgets erscheint ein Bestätigungsdialog mit den ausgewählten Widget-IDs. „Abbrechen“ oder Escape bricht ab; „Frage für die nächsten 5 Minuten unterdrücken“ überspringt weitere Löschfragen für fünf Minuten im geöffneten Editor. Löschen lässt sich weiterhin rückgängig machen.</li><li>Die Widget-Auswahl übernimmt einzelne Häkchen und die Auswahl aller Widgets sofort in die Editorfläche. Signalbilder, Extrasteuerung und Andockpunkte sind bei neuen Widgets standardmäßig deaktiviert und lassen sich bei Bedarf aktivieren.</li><li>Die Bildauswahl der Widgets verwendet ebenfalls <code>/config/www/studio</code>; übernommene und kopierte Bildpfade beginnen mit <code>/local/studio/</code>.</li><li>Mehrere Projekte und benannte Seiten mit eigenen Abmessungen, Hintergrund und Widgets verwalten. Die Runtime zeigt sichtbare Seiten separat an.</li><li>Widgets auf einer scrollbar erreichbaren Fläche platzieren, verschieben, skalieren, benennen und per z-index anordnen. Mehrfachauswahl, Ausrichtung, Größenabgleich, Kopieren, Einfügen sowie Rückgängig/Wiederholen sind im Editor vorhanden.</li><li>74 Widgets aus „HA Grafik – Basis“, „HA Grafik – Interaktiv“, „HA Grafik – Spezial“, „HA Grafik – Datenfluss“ und „HA Grafik – Gauges“ verwenden. Dazu gehören HTML, Bilder, Zahlen, Bedienelemente, Tabellen, Kalender, Dashboard-Einbettung, SVG-Linien, Berechnungen, Konverter und zehn Messinstrumente. Die Palette zeigt je nach Typ eine Vorschau oder ein Symbol.</li><li>Eigenschaften für Layout, CSS, „Generell“, Sichtbarkeit und Andockpunkte bearbeiten. Der Editor-Widget-Filter verwendet das Feld „Filterwort“ aus „Generell“.</li><li>Mit dem Spezial-Widget Verbindungslinien mit Zwischen- und explizit aktivierten Sammelpunkten, Farben, Pfeilspitzen und Animationen zeichnen. Kreuzende Linien koppeln sich nicht von selbst.</li><li>Dateien aus Home Assistants <code>/config/www/studio</code>-Ordner auswählen und unterstützte Dateien hochladen. Der Dateienbrowser legt diesen Stammordner beim Öffnen automatisch an. Falls Schreibrechte fehlen, erscheint ein Hinweis zum manuellen Erstellen. Der Entitätenbrowser kann Entitäten und aktuelle Zustände suchen und Entity-IDs in Widget-Felder übernehmen.</li><li>Änderungen automatisch nach einer einstellbaren Wartezeit speichern (standardmäßig fünf Sekunden) oder manuell speichern. Widgets lassen sich als JSON exportieren und importieren.</li><li>Die Oberfläche übernimmt die Home-Assistant-Sprache: Deutsch bei deutscher HA-Sprache, sonst Englisch. Unter <strong>Einstellungen → Sprache</strong> kann jeder Browser <strong>Automatisch</strong>, <strong>Deutsch</strong> oder <strong>English</strong> wählen. Projekt- und Widget-Inhalte bleiben dabei unverändert.</li></ul><h2 id="erganzungen-bis-0-1-158" tabindex="-1">Ergänzungen bis 0.1.158 <a class="header-anchor" href="#erganzungen-bis-0-1-158" aria-label="Permalink to &quot;Ergänzungen bis 0.1.158&quot;">​</a></h2><p>Die <a href="./widgets">Widget-Übersicht</a> erklärt jetzt die VIS2-inspirierten Wertelisten, Bool HTML/Checkbox/Select, Table, HTML State, Bar, HTML/Navigation, Filter, String und Input val mit Bildern. CSS Allgemein bleibt bei jedem Widget aktiv. Umsteigerhinweise lassen sich unter Einstellungen → Allgemein abschalten.</p><p><strong>Dashboard in widget</strong> unter Spezial bettet ein HA-Dashboard bis 800 × 640 Pixel ein. <strong>View in widget</strong> bleibt für Studio-Seiten zuständig. Unter <a href="./datenfluss">Datenfluss</a> stehen Wert-Verbindung, Wert-Konverter und Wert-Berechnung bereit; <a href="./svg-linebox-math">LineBox Math</a> bietet vier Rechnungen und eine einstellbare Darstellung.</p><h2 id="geplante-erweiterungen" tabindex="-1">Geplante Erweiterungen <a class="header-anchor" href="#geplante-erweiterungen" aria-label="Permalink to &quot;Geplante Erweiterungen&quot;">​</a></h2><p>Grafik Visual Studio soll künftig nicht nur zum Erstellen, sondern auch zum Verteilen und unabhängigen Anzeigen von Visualisierungen dienen. Die folgenden Punkte sind Entwicklungsziele. Sie beschreiben noch keine vollständig verfügbaren Funktionen; Umfang und Reihenfolge können sich durch Testergebnisse und Rückmeldungen ändern. Der aktuelle Funktionsumfang steht unter <strong>Was derzeit möglich ist</strong>.</p><ul><li><strong>Export und Import vollständiger Projekte:</strong> Projekte einschließlich benötigter Bilder, Einstellungen und Paketinformationen sichern, übertragen und auf einer anderen Installation wiederherstellen. Der geplante Projektpaket-Export ergänzt den vorhandenen JSON-Export einzelner Widgets.</li><li><strong>Separate Runtime auf einem eigenen Gerät:</strong> Fertige Visualisierungen unabhängig vom Editor betreiben, beispielsweise auf einem Raspberry Pi als Wanddisplay oder Bedienpanel. Die Verbindung zu Home Assistant soll konfigurierbar sein. Die vorhandene Runtime-Ansicht bildet die Grundlage; ein eigenständiges Runtime-Paket für separate Geräte ist ein weiteres Ziel.</li><li><strong>Koppel-App:</strong> Eine ergänzende Anwendung soll die Einrichtung und Verbindung zwischen Studio, Runtime und Home Assistant erleichtern. Der genaue Funktionsumfang wird noch festgelegt.</li><li><strong>Erweiterter Packer mit GitHub-Funktionen:</strong> Widget- und Tool-Pakete lokal erstellen und optional ein GitHub-Repository anlegen sowie Paketversionen dort veröffentlichen. Lokales Packen soll weiterhin ohne GitHub möglich sein. Weitere Informationen zum vorhandenen Werkzeug stehen unter <a href="./packer">Packer für Pakete</a>.</li><li><strong>Direkte Paketregistrierung aus dem Packer:</strong> Pakete beim <a href="https://visualstudio.ugso-software.de/?lang=de" target="_blank" rel="noreferrer">Community-Katalog</a> einreichen, mit derselben Registrierung und denselben Angaben zu Lizenz, Autor, Datenschutz und Studio-Kompatibilität wie auf der Webseite. Die Aufnahme in den öffentlichen Katalog erfolgt weiterhin nach Prüfung.</li></ul><h3 id="was-dazu-dokumentiert-werden-soll" tabindex="-1">Was dazu dokumentiert werden soll <a class="header-anchor" href="#was-dazu-dokumentiert-werden-soll" aria-label="Permalink to &quot;Was dazu dokumentiert werden soll&quot;">​</a></h3><ul><li><strong>Übertragbarkeit:</strong> Welche Ressourcen ein Export enthält, welche Erweiterungspakete am Ziel benötigt werden und welche Verbindungen dort neu eingerichtet werden müssen.</li><li><strong>Zugangsdaten:</strong> Wie Home-Assistant-Tokens und GitHub-Zugangsdaten behandelt werden. Ein normaler Projektexport soll keine unverschlüsselten Geheimnisse enthalten.</li><li><strong>Runtime-Voraussetzungen:</strong> Unterstützte Geräte, Einrichtung, Netzwerkverbindung und Verhalten bei einem Verbindungsabbruch.</li><li><strong>Paketpflege und Kompatibilität:</strong> Versionierung, Updates und das Zusammenspiel zwischen Studio, Runtime und Erweiterungspaketen.</li><li><strong>Mitmachen:</strong> Gesuchte Tester und Entwickler sowie Wege für Fehlerberichte und Vorschläge. Probleme können über die <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/issues" target="_blank" rel="noreferrer">GitHub-Issues</a> gemeldet werden. Wer über einen Forenbeitrag zum Projekt kommt, kann den Autor auch über die Chatfunktion dieses Forums kontaktieren; Erfahrung mit ioBroker VIS/VIS2 ist willkommen.</li></ul><h2 id="vorgemerkt-kalender-json-integration" tabindex="-1">Vorgemerkt: Kalender-JSON-Integration <a class="header-anchor" href="#vorgemerkt-kalender-json-integration" aria-label="Permalink to &quot;Vorgemerkt: Kalender-JSON-Integration&quot;">​</a></h2><p>Geplant ist eine eigene Home-Assistant-Integration, die HA-Kalender für Kalender-Widgets und andere Verbraucher als JSON-Terminlisten bereitstellt. Die Terminanzahl soll der Sensorzustand sein; die vollständige Liste liegt im Attribut <code>events</code>. Zeitraum und Aktualisierung sollen einstellbar sein. Die direkte <code>calendar.*</code>-Anbindung des Terminkalenders ist bereits vorhanden; die wiederverwendbare Integration ist noch nicht implementiert.</p><h2 id="grenzen-des-aktuellen-stands" tabindex="-1">Grenzen des aktuellen Stands <a class="header-anchor" href="#grenzen-des-aktuellen-stands" aria-label="Permalink to &quot;Grenzen des aktuellen Stands&quot;">​</a></h2><p>In der Runtime lesen Sensor, String, Red Number, Bar, Gauge und Bool HTML eine gebundene Home-Assistant-Entität alle fünf Sekunden; auch Sichtbarkeitsregeln verwenden diese Zustände. Ein Switch-Widget kann <code>switch</code>, <code>light</code> und <code>input_boolean</code> über HA-Dienste schalten und zeigt anschließend den bestätigten HA-Zustand. Die übrigen Daten- und Steuer-Widgets verwenden noch lokale Testwerte. Die Auswahl einer Entity-ID bedeutet dort noch keine Live-Anbindung. „Nur für Gruppen“ in der Sichtbarkeit und das Verhalten von <code>multi-views</code> sind noch nicht vollständig umgesetzt. Der Editor-Filter wirkt nur auf die Editoransicht.</p><p>Die App hat einen normalen Home-Assistant-Ingress-Eintrag. Getrennte Seitenleisteneinträge für Editor und Runtime erfordern zusätzlich die experimentelle Integration aus <code>custom_components/ha_grafik_visual_studio</code>; sie setzt Home Assistant OS oder Supervised mit Supervisor voraus. Die <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/ha_grafik_visual_studio/README.md" target="_blank" rel="noreferrer">Repository-README</a> enthält die Installationsschritte.</p><p>Die Bedienung ist von VIS2 inspiriert. Grafik Visual Studio ist eine eigenständige Implementierung; VIS2-Code und VIS2-Widgets werden nicht mitgeliefert.</p>',43)])])}const k=i(s,[["render",d]]);export{m as __pageData,k as default};
